-- ============================================================
-- Solar Kita: complete demo database (schema additions + data for every resident)
-- Generated from the app's own data (src/data.ts) so ids, prices, units and
-- holdings match what the app shows.
--
-- Run in the Supabase SQL Editor after schema.txt. Safe to re-run.
-- WARNING: this wipes every public.* table and re-creates demo data.
-- It also deletes the old demo user 7ea49052-2efb-43a6-9e49-de479be5721a.
--
-- Residents: 12 demo neighbours (neighbour01..12@demo.solarkita.my, sign in by email).
-- Each one has holdings, contributions and monthly credits, a points history,
-- redemptions, notifications, and some have Go Green trips, a Solar Builder Plan
-- and EV charging sessions. "Reset demo data" in the app restores the same state
-- (server/src/mockdata.js is generated alongside this file).
-- ============================================================

-- ----------------------------
-- 0. Schema additions (all idempotent)
-- ----------------------------
alter table public.townships
  add column if not exists map_seed integer,
  add column if not exists map_layout jsonb;

alter table public.sites
  add column if not exists grid_cols integer not null default 1 check (grid_cols > 0),
  add column if not exists map_x smallint check (map_x between 0 and 3),
  add column if not exists map_z smallint check (map_z between 0 and 3),
  add column if not exists output_pct numeric(5,2) check (output_pct between 0 and 100),
  add column if not exists blocks_per_row smallint not null default 1 check (blocks_per_row between 1 and 8);

-- Go Green (same as green.sql)

-- New activity kinds for the points ledger. (ADD VALUE must commit before
-- it can be used, which is why this file has no surrounding transaction.)
alter type public.activity_type add value if not exists 'walk';
alter type public.activity_type add value if not exists 'cycle';

create table if not exists public.green_trips (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  township_id text references public.townships(id) on delete set null,
  mode text not null check (mode in ('walk', 'cycle')),
  -- 'gps' = recorded on the phone, 'demo' = the app's demo route
  source text not null default 'gps' check (source in ('gps', 'demo')),
  started_at timestamptz not null,
  ended_at timestamptz not null,
  -- all figures below are computed by the server from the GPS path
  distance_km numeric(8,3) not null check (distance_km >= 0),
  duration_min numeric(8,2) not null check (duration_min > 0),
  inside_pct numeric(5,2) not null check (inside_pct between 0 and 100),
  points integer not null default 0 check (points >= 0),
  co2_saved_kg numeric(10,3) not null default 0,
  petrol_saved_l numeric(10,3) not null default 0,
  -- simplified route [[lat, lon], ...] for drawing the trip
  path jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  constraint trip_time_order check (ended_at > started_at)
);

create index if not exists green_trips_user_date_idx on public.green_trips(user_id, started_at desc);

alter table public.green_trips enable row level security;

drop policy if exists green_trips_select_own on public.green_trips;
create policy green_trips_select_own on public.green_trips
for select to authenticated using (user_id = (select auth.uid()));

-- trips (and their points) are only written by the trusted backend
revoke insert, update, delete on public.green_trips from anon, authenticated;
grant select on public.green_trips to authenticated;

-- Solar Builder Plan (same as plan.sql)

-- points-ledger activity for plan payments and streak bonuses (must commit before use,
-- which is why this file has no surrounding transaction)
alter type public.activity_type add value if not exists 'plan';

create table if not exists public.builder_plans (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  -- the solar farm the resident's payments support
  site_id text not null references public.sites(id) on delete restrict,
  monthly_amount numeric(14,2) not null check (monthly_amount between 50 and 10000),
  status text not null default 'active' check (status in ('active', 'paused', 'cancelled')),
  -- day of the month payments are taken (1-28)
  charge_day smallint not null check (charge_day between 1 and 28),
  next_charge_at timestamptz,
  -- consecutive monthly payments (resets when paused)
  streak integer not null default 0 check (streak >= 0),
  started_at timestamptz not null default now(),
  cancelled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- one running (active or paused) plan per resident
create unique index if not exists builder_plans_one_open_idx
  on public.builder_plans(user_id) where status <> 'cancelled';

create table if not exists public.builder_payments (
  id uuid primary key default gen_random_uuid(),
  plan_id uuid not null references public.builder_plans(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  -- 1, 2, 3... within the plan
  seq integer not null check (seq > 0),
  amount numeric(14,2) not null check (amount > 0),
  paid_at timestamptz not null,
  points integer not null default 0 check (points >= 0),
  created_at timestamptz not null default now(),
  unique (plan_id, seq)
);

create index if not exists builder_payments_plan_idx on public.builder_payments(plan_id, seq);

-- link plan money to the existing ledgers (deleted with the payment)
alter table public.contributions
  add column if not exists plan_payment_id uuid references public.builder_payments(id) on delete cascade;
alter table public.payouts
  add column if not exists plan_payment_id uuid references public.builder_payments(id) on delete cascade;
create index if not exists payouts_plan_payment_idx on public.payouts(plan_payment_id);

drop trigger if exists builder_plans_set_updated_at on public.builder_plans;
create trigger builder_plans_set_updated_at
before update on public.builder_plans
for each row execute function public.set_updated_at();

alter table public.builder_plans enable row level security;
alter table public.builder_payments enable row level security;

drop policy if exists builder_plans_select_own on public.builder_plans;
create policy builder_plans_select_own on public.builder_plans
for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists builder_payments_select_own on public.builder_payments;
create policy builder_payments_select_own on public.builder_payments
for select to authenticated using (user_id = (select auth.uid()));

-- plans and payments are only written by the trusted backend
revoke insert, update, delete on public.builder_plans, public.builder_payments from anon, authenticated;
grant select on public.builder_plans, public.builder_payments to authenticated;

-- EV charging (same as ev.sql)

-- points-ledger activity for paid charging sessions (must commit before use,
-- which is why this file has no surrounding transaction)
alter type public.activity_type add value if not exists 'charge';
-- notifications about bookings and charging sessions
alter type public.alert_type add value if not exists 'ev_charging';

create table if not exists public.ev_bookings (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  -- an EV station (a site of kind 'ev'); bays are its units, 0-based
  site_id text not null references public.sites(id) on delete restrict,
  bay smallint not null check (bay >= 0),
  starts_at timestamptz not null,
  hours smallint not null check (hours between 1 and 4),
  -- booked -> charging -> awaiting_payment -> paid, or cancelled / missed
  status text not null default 'booked'
    check (status in ('booked', 'charging', 'awaiting_payment', 'paid', 'cancelled', 'missed')),
  energy_kwh numeric(8,2) check (energy_kwh >= 0),
  -- the part of energy_kwh delivered during the solar peak
  peak_kwh numeric(8,2) check (peak_kwh >= 0),
  amount numeric(10,2) check (amount >= 0),
  points integer check (points >= 0),
  started_at timestamptz,
  finished_at timestamptz,
  paid_at timestamptz,
  cancelled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists ev_bookings_user_idx on public.ev_bookings(user_id, starts_at desc);

-- one row per booked hour; the unique key stops two bookings sharing a bay in the same hour
create table if not exists public.ev_booking_slots (
  booking_id uuid not null references public.ev_bookings(id) on delete cascade,
  site_id text not null references public.sites(id) on delete cascade,
  bay smallint not null,
  slot_start timestamptz not null,
  primary key (booking_id, slot_start),
  unique (site_id, bay, slot_start)
);

create index if not exists ev_booking_slots_site_idx on public.ev_booking_slots(site_id, slot_start);

drop trigger if exists ev_bookings_set_updated_at on public.ev_bookings;
create trigger ev_bookings_set_updated_at
before update on public.ev_bookings
for each row execute function public.set_updated_at();

alter table public.ev_bookings enable row level security;
alter table public.ev_booking_slots enable row level security;

drop policy if exists ev_bookings_select_own on public.ev_bookings;
create policy ev_bookings_select_own on public.ev_bookings
for select to authenticated using (user_id = (select auth.uid()));

-- bookings and bay holds are only written by the trusted backend
revoke insert, update, delete on public.ev_bookings, public.ev_booking_slots from anon, authenticated;
grant select on public.ev_bookings to authenticated;

-- the new point types ('walk', 'cycle', 'plan', 'charge') must be committed before the data uses them
commit;

begin;

-- ----------------------------
-- 1. Reset
-- ----------------------------
truncate table
  public.messages, public.conversations, public.notification_deliveries, public.alert_reads,
  public.alerts, public.alert_incidents, public.notification_preferences, public.solar_readings,
  public.daily_checkins, public.redemptions, public.point_ledger, public.payouts, public.contributions,
  public.subscription_units, public.subscriptions, public.green_trips, public.builder_payments,
  public.builder_plans, public.ev_booking_slots, public.ev_bookings,
  public.profiles, public.rewards, public.sites, public.townships
restart identity cascade;

-- the old demo user and the demo neighbours (re-created below)
delete from auth.users where id = '7ea49052-2efb-43a6-9e49-de479be5721a' or email like '%@demo.solarkita.my';

